import os, re, json

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
G = {}

for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows_raw = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows_raw):
        G[k] = [[int(x) for x in r] for r in rows_raw]

def solve(grid):
    # Find spacing (demo had 4, test seems to have 5 based on line analysis)
    if len(grid) <= 1:
        return grid

    # Analyze structure - find horizontal lines of 8s
    lines_h = []
    for r in range(len(grid)):
        if all(grid[r][c] == 8 for c in range(len(grid[r]))):
            lines_h.append(r)

    if len(lines_h) < 2:
        return grid

    spacing = lines_h[1] - lines_h[0]
    num_cells = (len(grid) // spacing) + 1  # Estimate number of cells

    # Initialize output
    output = [[0]*len(grid[0]) for _ in range(len(grid))]

    # For each cell, find its value and replicate
    for r_cell in range(num_cells):
        for c_cell in range(num_cells):
            start_r = r_cell * spacing
            start_c = c_cell * spacing

            # Find value in this cell (center pixel or any non-8 non-0)
            cell_start_min_r = max(0, start_r - spacing//2)
            cell_end_max_r = min(len(grid)-1, start_r + spacing)
            cell_start_min_c = max(0, start_c - spacing//2)
            cell_end_max_c = min(len(grid[0])-1, start_c + spacing)

            cell_val = None
            for rr in range(cell_start_min_r, cell_end_max_r):
                for cc in range(cell_start_min_c, cell_end_max_c):
                    if grid[rr][cc] != 0 and grid[rr][cc] != 8:
                        cell_val = grid[rr][cc]
                        break
                if cell_val:
                    break

            if cell_val is not None:
                # Fill the cell region
                for rr in range(start_r, start_r + spacing):
                    for cc in range(start_c, start_c + spacing):
                        output[rr][cc] = cell_val

    return output

